//! Golden tests: `uri_template::expand` against the unmodified C++
//! `uri_template::Expand` (net/third_party/uri_template/uri_template.cc).
//!
//! The C++ was built with g++ 13 (-std=c++23). Its dependencies were
//! replaced by stand-in headers, and the escaping functions were taken from
//! the real base/strings/escape.cc (charmaps and Escape) and compiled as-is:
//! - base/component_export.h: COMPONENT_EXPORT defined as nothing.
//! - absl::flat_hash_map: std::unordered_map with a transparent hash.
//! - base/strings/strcat.h and string_split.h: re-implemented for the
//!   configurations uri_template.cc uses (see the harness shim).
//! - base/strings/escape.h: declarations only. The two functions are
//!   compiled from a verbatim extract of escape.cc. AppendHexEncodedByte and
//!   IsHexDigit are copied from their headers.
//!
//! The C++ was run on each template with the same parameter map as
//! uri_template_test.cc. Cases are 498 templates (323 expand successfully),
//! from a fixed set of hand-written templates and a seeded random generator.
//! The generator is not part of the Rust tests. Only the recorded outputs are
//! checked in.

use std::collections::{BTreeSet, HashMap};

use uri_template::expand;

fn parameters() -> HashMap<Vec<u8>, Vec<u8>> {
    let pairs: &[(&[u8], &[u8])] = &[
        (b"var", b"value"),
        (b"hello", b"Hello World!"),
        (b"path", b"/foo/bar"),
        (b"empty", b""),
        (b"x", b"1024"),
        (b"y", b"768"),
        (b"percent", b"%31"),
        (b"bad_percent", b"%1"),
        (b"escaped", b" !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~\x80\xFF"),
    ];
    pairs.iter().map(|(k, v)| (k.to_vec(), v.to_vec())).collect()
}

// (template, expected to be valid, expected expansion, expected vars).
// For invalid templates the expansion is empty, as the C++ clears it.
type Case = (&'static [u8], bool, &'static [u8], &'static [&'static [u8]]);

