#[test]
fn matches_cpp_expand() {
    let params = parameters();
    for (template, valid, expected, expected_vars) in CASES {
        let mut found = BTreeSet::new();
        let result = expand(template, &params, Some(&mut found));
        assert_eq!(result.is_ok(), *valid, "validity of {template:?}");
        let output = result.unwrap_or_default();
        assert_eq!(output.as_slice(), *expected, "expansion of {template:?}");
        let expected_set: BTreeSet<Vec<u8>> = expected_vars.iter().map(|n| n.to_vec()).collect();
        assert_eq!(found, expected_set, "vars of {template:?}");
    }
}
